// Room "P3 living room" (interior designer's part): the Puritan's front parlour, hearth in the west wall at z17.
// Inner air x52..54, y2..4, z14..20. Floor layer y1 (the floor block), so furniture stands at y2.
// Layout: rug in front of the hearth (x52..53, z17..18); sofa of two stairs on the east wall (x54, z15..16, back to
// the wall) facing a spruce-fence table with a top slab (x53, z16); a standing lantern by the hearth; a potted plant
// and a chest under the windows; a candle on the table and a hanging lantern for the centre of the room. The east
// column x54 is kept clear at z14, z17..20 (the hall doorways) and the back row z20 at x53..54 (the back doors).
import { layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

export function build(g) {
  // y2 (feet): furniture on the floor
  layers(g, [52, 2, 14], {
    c: ["chest", { facing: "east" }],
    p: "potted_poppy",
    L: ["lantern", { hanging: "false" }],
    f: "spruce_fence",
    S: ["spruce_stairs", { facing: "east", half: "bottom" }],
    r: "red_carpet",
    b: "barrel",
  }, [
    ["c..", "p.S", "LfS", "rr.", "rr.", "b..", "..."],
  ]);

  // y3: the table's top slab (top half, so a candle stands on it at y4)
  layers(g, [52, 3, 14], {
    t: ["spruce_slab", { type: "top" }],
  }, [
    ["...", "...", ".t.", "...", "...", "...", "..."],
  ]);

  // y4: a candle on the table, a hanging lantern hung from the ceiling at the room's centre line
  layers(g, [52, 4, 14], {
    a: ["candle", { candles: "2", lit: "true" }],
    h: ["lantern", { hanging: "true" }],
  }, [
    ["...", "...", ".a.", "...", ".h.", "...", "..."],
  ]);
}
